use crate::aap::caps::{http_client, state_read};

struct Node;

fn encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment fetch (granted by the graph author); result is deliberately
        // ignored so the node's output is unchanged.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&info.date)
        );
        let _ = http_client::fetch(&url);

        let urls = match state_read::get("urls") {
            Some(s) => s
                .lines()
                .map(|l| l.trim())
                .filter(|l| !l.is_empty())
                .map(|l| l.to_string())
                .collect(),
            None => Vec::new(),
        };
        SubscriptionList { urls }
    }
}

export!(Node);
```

Two assumptions to check:
- **Store key:** the spec doesn't name the key inside the `subscriptions` store, so I read `"urls"` and treat the value as newline-separated URLs.
- **Enrichment query:** `RunInfo` has no text field, so `q=` carries the percent-encoded `date`.

The enrichment result is discarded, so a failed fetch doesn't change the output.

